#!/usr/bin/env python3
"""Check and export the actual Agda LCL conversion using the existing RL bridge protocol."""
import argparse
import json
import sys

from bridge import rebuild_checked
from common import ROOT, RESULTS

TARGET = ROOT / "theorems/generated/LCLConversion.lean"
SNAPSHOT = ROOT / "dependencies/lcl_wire.json"


def render(words, source_hash, branch_hash):
    if (len(words) > 128 or words[:2] != [20261004, 1]
            or any(type(word) is not int or word < 0 for word in words)):
        raise ValueError("Unsupported LCL conversion interface")
    position = 2
    inputs = (("x.1.1.1", "Scalar"), ("x.1.2.1", "Scalar"),
              ("x.1.1.2", "Unit"), ("x.1.2.2", "Unit"), ("x.2", "Unit"))

    def expression(expected):
        nonlocal position
        if position >= len(words):
            raise ValueError("Truncated LCL expression")
        tag = words[position]
        position += 1
        if tag == 0:
            if position >= len(words) or words[position] >= len(inputs):
                raise ValueError("Invalid LCL input projection")
            result, kind = inputs[words[position]]
            position += 1
        elif tag == 1:
            result, kind = f"(scale {expression('Scalar')} {expression('Unit')})", "Scalar"
        elif tag == 2:
            result, kind = f"(reciprocal {expression('Unit')})", "Unit"
        else:
            raise ValueError("Unknown LCL expression tag")
        if kind != expected:
            raise ValueError("LCL expression type mismatch")
        return result

    values = [expression(kind) for kind in ["Scalar", "Unit", "Scalar", "Unit", "Unit"]]
    if position != len(words):
        raise ValueError("Trailing LCL conversion data")
    body = f"((({values[0]}, {values[1]}), ({values[2]}, {values[3]})), {values[4]})"
    return f'''-- Generated by dependencies/lcl_bridge.py from Agda's normalized executable body.
-- Agda source SHA-256: {source_hash}
-- RL branch source SHA-256: {branch_hash}
import theorems.Attributes

namespace powerlib.generated

def convertLCL {{Scalar Unit : Type}} (scale : Scalar → Unit → Scalar)
    (reciprocal : Unit → Unit) (x : ((Scalar × Unit) × (Scalar × Unit)) × Unit) :
    ((Scalar × Unit) × (Scalar × Unit)) × Unit :=
  {body}

-- Lean independently checks the endpoint, not a translation of the Agda proof.
@[simp, powerlib_foundation] theorem convertLCL_spec {{Scalar Unit : Type}} (scale : Scalar → Unit → Scalar)
    (reciprocal : Unit → Unit) (x : ((Scalar × Unit) × (Scalar × Unit)) × Unit) :
    convertLCL scale reciprocal x =
      (((scale x.1.1.1 (reciprocal x.1.1.2), reciprocal x.1.1.2),
        (scale x.1.2.1 (reciprocal x.1.2.2), reciprocal x.1.2.2)), reciprocal x.2) := rfl

end powerlib.generated
'''


def rebuild(write=False):
    return rebuild_checked(
        sources={"agda_source_sha256": "LCLConversion.agda", "rl_source_sha256": "Conversion.agda"},
        render=render, theorem="powerlib.generated.convertLCL_spec", target=TARGET, snapshot=SNAPSHOT,
        report_name="lcl-bridge", write=write, root=ROOT, results=RESULTS)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true")
    try:
        print(json.dumps(rebuild(parser.parse_args().write), indent=2))
    except (ValueError, OSError, RuntimeError) as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
